-- Products (one per distinct name)      : 1089  P0001..P1089
-- Warehouse 'main' stock rows          : 1089 (346 with stock, 63348 units)
-- POS001 vehicle stock (vehicle_POS001): 431 products, 28750 units
-- POS002 vehicle stock (store_00001)   : 445 products, 23731 units
--
-- DESTRUCTIVE. Drops the catalog and every document that references it
-- (bills, returns, stock counts, transfers, purchase orders, daily closes)
-- so the rebuilt catalog carries no retired codes. Users, roles, branches,
-- stores, POS settings, units, categories and sessions are left untouched.
-- Take a pg_dump of schema 'public' before running this.
--
-- Each vehicle's stock is issued out of the warehouse by one completed
-- pos_restock transfer, mirroring what the app writes on completion.
-- =============================================================================

BEGIN;

-- Guard: everything this seed writes against must already exist.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM store_master WHERE id = 'main' AND location_type = 'warehouse') THEN
    RAISE EXCEPTION 'warehouse main is missing';
  END IF;
  IF (SELECT count(*) FROM store_master WHERE location_type = 'warehouse') <> 1 THEN
    RAISE EXCEPTION 'expected exactly one warehouse';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pos_setting WHERE pos_id = 'POS001'
                   AND vehicle_store_id = 'vehicle_POS001' AND branch_id = '00001') THEN
    RAISE EXCEPTION 'POS001 is not bound to vehicle_POS001/00001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pos_setting WHERE pos_id = 'POS002'
                   AND vehicle_store_id = 'store_00001' AND branch_id = '00002') THEN
    RAISE EXCEPTION 'POS002 is not bound to store_00001/00002';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "user" WHERE username = 'admin') THEN
    RAISE EXCEPTION 'user admin is missing';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM unit_master WHERE id = 'pcs') THEN
    RAISE EXCEPTION 'unit pcs is missing';
  END IF;
END $$;

-- 1. Clear the catalog and every document that references it, children first.
DELETE FROM bill_discount_detail;
DELETE FROM return_note_item_detail;
DELETE FROM return_note_master;
DELETE FROM bill_item_detail;
DELETE FROM bill_master;
DELETE FROM stock_count_item;
DELETE FROM stock_count;
DELETE FROM inventory_transfer_audit;
DELETE FROM inventory_transfer_item;
DELETE FROM inventory_transfer;
DELETE FROM purchase_order_item;
DELETE FROM purchase_order;
DELETE FROM cash_reconciliation;
DELETE FROM daily_close;
DELETE FROM address_master;
DELETE FROM part_master;

-- Document counters restart with the clean history; branch/member counters stay.
DELETE FROM counter WHERE key ~ '^[a-z]*_?[0-9]{8}$';

