INSERT INTO counter (key, value) VALUES ('tr_20260808', 2)
ON CONFLICT (key) DO UPDATE SET value = GREATEST(counter.value, EXCLUDED.value);

-- Post-conditions: the three rules this rebuild exists to satisfy.
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM part_master;
  IF n <> 1089 THEN
    RAISE EXCEPTION 'expected 1089 products, found %', n;
  END IF;

  -- rule 1: one warehouse, every product in it exactly once, no repeated names
  SELECT count(*) INTO n FROM store_master WHERE location_type = 'warehouse';
  IF n <> 1 THEN RAISE EXCEPTION 'expected exactly one warehouse, found %', n; END IF;
  SELECT count(*) INTO n FROM address_master WHERE store_id = 'main';
  IF n <> 1089 THEN
    RAISE EXCEPTION 'warehouse should hold all 1089 products, holds %', n;
  END IF;
  SELECT count(*) INTO n FROM (
    SELECT lower(btrim(name)) FROM part_master GROUP BY 1 HAVING count(*) > 1) d;
  IF n <> 0 THEN RAISE EXCEPTION '% product names occur more than once', n; END IF;
  SELECT count(*) INTO n FROM (
    SELECT part_code, store_id FROM address_master GROUP BY 1, 2 HAVING count(*) > 1) d;
  IF n <> 0 THEN RAISE EXCEPTION '% products have two rows in one store', n; END IF;

  -- rules 2 and 3: each vehicle holds exactly what its block lists, and
  -- every unit it holds is covered by a completed issue out of the warehouse
  SELECT count(*) INTO n FROM address_master WHERE store_id = 'vehicle_POS001';
  IF n <> 431 THEN
    RAISE EXCEPTION 'vehicle_POS001 should hold 431 products, holds %', n;
  END IF;
  SELECT COALESCE(sum(qty), 0) INTO n FROM address_master WHERE store_id = 'vehicle_POS001';
  IF n <> 28750 THEN
    RAISE EXCEPTION 'vehicle_POS001 should hold 28750 units, holds %', n;
  END IF;
  SELECT COALESCE(sum(i.received_qty), 0) INTO n FROM inventory_transfer_item i
   WHERE i.transfer_id = 'TR20260808000001';
  IF n <> 28750 THEN
    RAISE EXCEPTION 'issue document for vehicle_POS001 covers % units, expected 28750', n;
  END IF;
  IF EXISTS (SELECT 1 FROM address_master a
              WHERE a.store_id = 'vehicle_POS001'
                AND NOT EXISTS (SELECT 1 FROM address_master m
                                 WHERE m.part_code = a.part_code AND m.store_id = 'main')) THEN
    RAISE EXCEPTION 'vehicle_POS001 holds a product that is not registered in the warehouse';
  END IF;
  SELECT count(*) INTO n FROM address_master WHERE store_id = 'store_00001';
  IF n <> 445 THEN
    RAISE EXCEPTION 'store_00001 should hold 445 products, holds %', n;
  END IF;
  SELECT COALESCE(sum(qty), 0) INTO n FROM address_master WHERE store_id = 'store_00001';
  IF n <> 23731 THEN
    RAISE EXCEPTION 'store_00001 should hold 23731 units, holds %', n;
  END IF;
  SELECT COALESCE(sum(i.received_qty), 0) INTO n FROM inventory_transfer_item i
   WHERE i.transfer_id = 'TR20260808000002';
  IF n <> 23731 THEN
    RAISE EXCEPTION 'issue document for store_00001 covers % units, expected 23731', n;
  END IF;
  IF EXISTS (SELECT 1 FROM address_master a
              WHERE a.store_id = 'store_00001'
                AND NOT EXISTS (SELECT 1 FROM address_master m
                                 WHERE m.part_code = a.part_code AND m.store_id = 'main')) THEN
    RAISE EXCEPTION 'store_00001 holds a product that is not registered in the warehouse';
  END IF;
END $$;

COMMIT;
